import{_ as e,o as a,c as t,Q as o}from"./chunks/framework.b67c47e6.js";const r="/assets/dashboard.673fcb31.png",n="/assets/dashboard-screen.f95e2e8e.png",b=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/dashboard/index.md","filePath":"guide/management/dashboard/index.md","lastUpdated":1793289309000}'),s={name:"guide/management/dashboard/index.md"},i=o('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The Dashboard gathers production indicators in one place. It is visible in company-wide mode and reserved for managers and admins.</p><h2 id="how-to-open-it" tabindex="-1">How to open it <a class="header-anchor" href="#how-to-open-it" aria-label="Permalink to &quot;How to open it&quot;">​</a></h2><p>In the left menu, switch to company-wide mode and click <strong>Dashboard</strong> at the top of the list.</p><p><img src="'+r+'" alt="The Dashboard"></p><h2 id="period-and-production-lines" tabindex="-1">Period and production lines <a class="header-anchor" href="#period-and-production-lines" aria-label="Permalink to &quot;Period and production lines&quot;">​</a></h2><p>Two controls next to the title apply to the whole page:</p><ul><li><strong>Period</strong>: <em>Last 14 days</em> (one mark per day), <em>Last 4 weeks</em>, <em>Last 12 weeks</em> (the default), <em>This year</em> or <em>Last year</em> (one mark per ISO week, Monday-based).</li><li><strong>Production lines</strong>: leave it empty to see every line, or pick the lines you want. Every chart split by line follows it.</li></ul><p>Both are remembered on this device. On a phone they are behind the <strong>Filters</strong> button.</p><p>Every card opens with its main figure, so you can read it without hovering over the chart.</p><h2 id="choosing-the-charts" tabindex="-1">Choosing the charts <a class="header-anchor" href="#choosing-the-charts" aria-label="Permalink to &quot;Choosing the charts&quot;">​</a></h2><p>The cog button at the top right opens <strong>Dashboard settings</strong>, a list of every chart grouped by theme (Events, Throughput, Pipeline, Quality, Planning). Untick a chart to hide it, or untick a group to hide all its charts. The choice is remembered on this device.</p><p>The same menu opens the <a href="#factory-screen">factory screen</a>.</p><h2 id="colours" tabindex="-1">Colours <a class="header-anchor" href="#colours" aria-label="Permalink to &quot;Colours&quot;">​</a></h2><p>The colours mean the same thing on every chart:</p><ul><li><strong>Status</strong> colours are the ones of the status chips in the rest of the app: <em>Waiting</em> grey, <em>Working</em> blue, <em>Ready</em> green. <em>Stalled</em> is orange.</li><li><strong>A production line keeps one colour</strong> on every chart and for every period. When more than seven lines are shown, the rest are grouped under a grey <em>Other</em>; pick lines in the filter to see them on their own.</li></ul><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h2><h3 id="today-s-activity" tabindex="-1">Today&#39;s activity <a class="header-anchor" href="#today-s-activity" aria-label="Permalink to &quot;Today&#39;s activity&quot;">​</a></h3><p>A timeline of today&#39;s events since midnight, with one lane per production line and a <strong>Now</strong> marker. It shows panels and modules marked ready, stations finished, and issues opened or resolved. The counter next to the title gives the number of events, and the refresh button reloads them.</p><h3 id="assemblies-marked-ready" tabindex="-1">Assemblies marked ready <a class="header-anchor" href="#assemblies-marked-ready" aria-label="Permalink to &quot;Assemblies marked ready&quot;">​</a></h3><p>How many panels each production line marked as ready, one column per week (or per day), stacked by line, with the total above each column. The figure on top is the current week against the average of the finished weeks of the period.</p><p>The <strong>Panels | m²</strong> switch counts the panels or their net area. Area makes weeks comparable when panel sizes differ: a lintel and a full wall are both one panel. Panels whose design has no area yet are not counted in m², and the card says how many.</p><h3 id="projects-in-production" tabindex="-1">Projects in production <a class="header-anchor" href="#projects-in-production" aria-label="Permalink to &quot;Projects in production&quot;">​</a></h3><p>The projects with production in the period, latest activity first. For each one: a bar with the panels ready (green) and being worked on (blue) out of the total, the panels working and stalled, and the last activity. It follows the <strong>Panels | m²</strong> switch. Click a project to open it.</p><h3 id="active-backlog" tabindex="-1">Active backlog <a class="header-anchor" href="#active-backlog" aria-label="Permalink to &quot;Active backlog&quot;">​</a></h3><p>Panels still to produce in the projects that had production in the period, per production line, split by status: <em>Waiting</em>, <em>Working</em> and <em>Stalled</em>. <em>Working</em> only counts panels with production activity in the last 7 days; the rest are <em>Stalled</em>.</p><h3 id="stalled-panels" tabindex="-1">Stalled panels <a class="header-anchor" href="#stalled-panels" aria-label="Permalink to &quot;Stalled panels&quot;">​</a></h3><p>Panels set to <em>Working</em> with no production activity for 7 days, per project, with their lines and the oldest last activity. <strong>Show</strong> opens the project&#39;s working panels in <strong>Constructibles</strong>, where you can set them ready or back to waiting. Panels left in <em>Working</em> after they were built or dropped are counted here until someone closes them.</p><h3 id="ready-to-build" tabindex="-1">Ready to build <a class="header-anchor" href="#ready-to-build" aria-label="Permalink to &quot;Ready to build&quot;">​</a></h3><p>Unbuilt panels per production line, split by whether their material is there: <em>Kitted parts</em>, <em>Partly cut</em>, <em>Not cut yet</em> and <em>No parts recorded</em>. The large number at the top says how many can be built now, out of all still to build. This chart only appears when the company tracks kitted parts (see <a href="/guide/management/#interface-settings">Company settings</a>).</p><h3 id="pending-delivery" tabindex="-1">Pending delivery <a class="header-anchor" href="#pending-delivery" aria-label="Permalink to &quot;Pending delivery&quot;">​</a></h3><p>Produced panels that are not mounted yet, per production line, split by delivery status: <em>Unknown</em>, <em>In rack</em> and <em>Delivered</em>. This chart only appears once the company has panels in a rack or delivered (see <a href="/guide/logistics/delivery/">Delivery</a>).</p><h3 id="panels-per-station" tabindex="-1">Panels per station <a class="header-anchor" href="#panels-per-station" aria-label="Permalink to &quot;Panels per station&quot;">​</a></h3><p>How many panels each station finished, per week, as a grid: one row per station (named <em>Line · Station</em>), one column per week, darker for more panels. The busiest stations come first; <strong>Show all</strong> lists the rest. A station lighter than the ones before it on the same line is where panels pile up.</p><h3 id="issues-per-100-panels" tabindex="-1">Issues per 100 panels <a class="header-anchor" href="#issues-per-100-panels" aria-label="Permalink to &quot;Issues per 100 panels&quot;">​</a></h3><p>Issues opened per week, by category (<em>Quality control</em>, <em>Production</em>), with the rate per 100 panels marked ready in the period as the main figure. Hover a column to see the panels of that week.</p><h3 id="on-time-production-and-forecast-vs-progress" tabindex="-1">On-time production and Forecast vs progress <a class="header-anchor" href="#on-time-production-and-forecast-vs-progress" aria-label="Permalink to &quot;On-time production and Forecast vs progress&quot;">​</a></h3><p>These two charts appear only when the company works by dates (<em>Production list based on dates</em> in Company settings).</p><ul><li><strong>On-time production</strong>: per week, the share of panels marked ready on or before their scheduled production date, against a 100% target line. Panels with no scheduled date are left out, and a week without any is left blank.</li><li><strong>Forecast vs progress</strong>: for this week and the three after it, the panels scheduled that week, split into <em>Done</em>, <em>In progress</em> and <em>Pending</em>, with the share done above each column.</li></ul><h2 id="factory-screen" tabindex="-1">Factory screen <a class="header-anchor" href="#factory-screen" aria-label="Permalink to &quot;Factory screen&quot;">​</a></h2><p><strong>Dashboard settings → Open factory screen</strong> opens a full-screen view for a TV on the shop floor or in the office:</p><ul><li><strong>Ready today</strong>, against how many are usually ready by this time of day (the average of the last four weeks&#39; working days);</li><li><strong>This week</strong>, against an average week, in panels or m² (the choice of the <strong>Panels | m²</strong> switch);</li><li><strong>Stalled panels</strong>;</li><li>one row per production line with the panels ready today, a mark for the usual count by now, and the panels being worked on now.</li></ul><p>It refreshes every minute on its own and keeps the screen awake. Bookmark its address in the TV&#39;s browser to open it straight away. The × at the top right goes back to the Dashboard.</p><p><img src="'+n+'" alt="The factory screen"></p><h2 id="custom-charts" tabindex="-1">Custom charts <a class="header-anchor" href="#custom-charts" aria-label="Permalink to &quot;Custom charts&quot;">​</a></h2><p>For a chart that is not here, use the <a href="/guide/mcp/">MCP connector</a>: Claude builds it from your company&#39;s data.</p>',46),h=[i];function l(d,c,p,m,u,g){return a(),t("div",null,h)}const f=e(s,[["render",l]]);export{b as __pageData,f as default};
